#pragma once

#include <systemc>

// How the per-cycle simulation loop advances SystemC time.
//
// The loop itself is the same either way (see Simulator::run). What differs is
// who owns the kernel:
//
//   * vsim's own binary owns it. sc_main runs the loop, and advancing means
//     starting the kernel for one period -- ScStartClock.
//   * Under FastSim the kernel owns vsim. FastSim's sc_main calls sc_start()
//     once, so the loop runs inside a process, where sc_start is illegal and
//     advancing means yielding for one period -- ScWaitClock.
//
// Callers hold a CycleClock& so that Simulator::run is compiled once, not once
// per ownership model.
class CycleClock
{
public:
  CycleClock() = default;
  CycleClock(const CycleClock&) = delete;
  auto operator=(const CycleClock&) -> CycleClock& = delete;
  virtual ~CycleClock() = default;

  virtual void advance(const sc_core::sc_time& period) = 0;
};

// For a caller that owns the kernel: sc_main, or anything else outside a
// SystemC process.
class ScStartClock final : public CycleClock
{
public:
  void advance(const sc_core::sc_time& period) override
  {
    sc_core::sc_start(period);
  }
};

// For a caller that runs inside the kernel: an SC_THREAD. Calling sc_start
// from here is an error the kernel reports, so the loop must yield instead.
class ScWaitClock final : public CycleClock
{
public:
  void advance(const sc_core::sc_time& period) override
  {
    sc_core::wait(period);
  }
};
EOF
